import * as Phaser from "phaser";
import { ASSET_KEYS, CAR_FRAME_KEYS } from "../../common/assets";
import {
  CAR_FREQUENCY_MS_MAX,
  CAR_FREQUENCY_MS_MIN,
} from "../../common/config";
import { logger } from "../../common/logger";
import type { TiledVehicleObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

enum CarDirection {
  LEFT_TO_RIGHT = "LEFT_TO_RIGHT",
  RIGHT_TO_LEFT = "RIGHT_TO_LEFT",
}

export class Car extends Phaser.Physics.Arcade.Sprite implements CustomObject {
  #isActive = false;
  #direction: CarDirection;
  #frameBase: string;
  #speed = 260; // pixels per second
  #timeEvent?: Phaser.Time.TimerEvent;
  #killZone: Phaser.GameObjects.Zone;
  #killZoneHeight: number;

  static readonly FRAME_BASES = [
    "car_red",
    "car_blue",
    "car_teal",
    "car_green",
    "car_orange",
    "car_gray",
  ] as const;
  static readonly CAR_KILL_ZONE_HEIGHT = 32;

  constructor(scene: Phaser.Scene, vehicleData: TiledVehicleObject) {
    const direction = Car.#inferDirection(vehicleData);
    const frameBase = Car.#randomFrameBase();
    const initialFrame = Car.#frameForDirection(
      scene.textures,
      frameBase,
      direction,
    );

    super(scene, vehicleData.x, vehicleData.y, ASSET_KEYS.CARS, initialFrame);

    this.#direction = direction;
    this.#frameBase = frameBase;

    scene.add.existing(this);
    scene.physics.add.existing(this);

    this.setOrigin(0.5, 0.5).setDepth(1.5).setImmovable(true).setVisible(false);

    this.#killZoneHeight = Math.min(
      Car.CAR_KILL_ZONE_HEIGHT,
      this.displayHeight,
    );

    if (this.body) {
      this.body.setSize(this.displayWidth, this.#killZoneHeight);
      this.body.setOffset(0, this.displayHeight - this.#killZoneHeight);
      this.body.enable = true;
    }

    this.#killZone = scene.add
      .zone(
        this.x - this.displayWidth / 2,
        this.y + this.displayHeight / 2 - this.#killZoneHeight,
        this.displayWidth,
        this.#killZoneHeight,
      )
      .setOrigin(0, 0);
    scene.physics.add.existing(this.#killZone);
  }

  enableObject(): void {
    this.#isActive = true;
    logger.info(
      `Enabling car color=${this.#frameBase} dir=${this.#direction} at y=${this.y}`,
    );
    this.#scheduleNextRun(0);
  }

  disableObject(): void {
    this.#isActive = false;

    if (this.#timeEvent) {
      this.#timeEvent.destroy();
      this.#timeEvent = undefined;
    }

    this.scene.tweens.killTweensOf(this);
    this.setVisible(false);
  }

  #scheduleNextRun(delay?: number): void {
    if (!this.#isActive) return;

    if (this.#timeEvent) {
      this.#timeEvent.destroy();
    }

    const randomizedDelay =
      delay ?? Phaser.Math.Between(CAR_FREQUENCY_MS_MIN, CAR_FREQUENCY_MS_MAX);

    this.#timeEvent = this.scene.time.addEvent({
      delay: randomizedDelay,
      callback: () => {
        this.#timeEvent = undefined;
        if (!this.#isActive) return;
        this.#runCar();
      },
    });
  }

  #runCar(): void {
    // Randomize color each run
    this.#frameBase = Car.#randomFrameBase();
    this.setFrame(
      Car.#frameForDirection(
        this.scene.textures,
        this.#frameBase,
        this.#direction,
      ),
    );

    const bounds = this.scene.cameras.main.getBounds();
    const startX =
      this.#direction === CarDirection.RIGHT_TO_LEFT
        ? bounds.right + this.displayWidth
        : bounds.left - this.displayWidth;
    const endX =
      this.#direction === CarDirection.RIGHT_TO_LEFT
        ? bounds.left - this.displayWidth
        : bounds.right + this.displayWidth;

    this.setVisible(true);
    this.setX(startX);

    const distance = Math.abs(endX - startX);
    const duration = (distance / this.#speed) * 1000;

    this.scene.tweens.add({
      targets: this,
      x: endX,
      duration,
      ease: "Linear",
      onUpdate: () => {
        // Keep kill zone in sync while tweening
        this.#syncKillZone();
      },
      onComplete: () => {
        this.setVisible(false);
        this.#syncKillZone();
        this.#scheduleNextRun();
      },
    });
  }

  #syncKillZone(): void {
    this.#killZone.x = this.x - this.displayWidth / 2;
    this.#killZone.y = this.y + this.displayHeight / 2 - this.#killZoneHeight;
  }

  public getKillZone(): Phaser.GameObjects.Zone {
    return this.#killZone;
  }

  static #inferDirection(vehicleData: TiledVehicleObject): CarDirection {
    // Force specific ids to lanes: 1/3 go left, 2/4 go right
    const numericId = Number(vehicleData.vehicleId);
    if (numericId === 1 || numericId === 3) {
      return CarDirection.RIGHT_TO_LEFT;
    }
    if (numericId === 2 || numericId === 4) {
      return CarDirection.LEFT_TO_RIGHT;
    }

    if (vehicleData.direction === "LTR") return CarDirection.LEFT_TO_RIGHT;
    if (vehicleData.direction === "RTL") return CarDirection.RIGHT_TO_LEFT;

    return CarDirection.LEFT_TO_RIGHT;
  }

  static #randomFrameBase(): string {
    const idx = Phaser.Math.Between(0, Car.FRAME_BASES.length - 1);
    return Car.FRAME_BASES[idx];
  }

  static #frameForDirection(
    textureManager: Phaser.Textures.TextureManager,
    frameBase: string,
    direction: CarDirection,
  ): string {
    const suffix = direction === CarDirection.LEFT_TO_RIGHT ? "right" : "left";
    const candidate = `${frameBase}_${suffix}.png`;
    const atlas = textureManager.get(ASSET_KEYS.CARS);
    if (atlas && !atlas.has(candidate)) {
      return direction === CarDirection.LEFT_TO_RIGHT
        ? CAR_FRAME_KEYS.RED_RIGHT
        : CAR_FRAME_KEYS.RED_LEFT;
    }
    return candidate;
  }
}
