import * as Phaser from "phaser";
import { ASSET_KEYS, TRAFFIC_LIGHTS_FRAME_KEYS } from "../../common/assets";
import type { CustomObject } from "../../common/types";

const COLOR_DURATION_MS = 1000;
const DIGIT_GAP_MS = 250;
const LETTER_GAP_MS = 1000;

type TrafficLightConfig = {
  x: number;
  y: number;
  ternaryLetters: string[];
  startOffsetMs?: number;
  usePoleVariant?: boolean;
};

type FrameKey =
  (typeof TRAFFIC_LIGHTS_FRAME_KEYS)[keyof typeof TRAFFIC_LIGHTS_FRAME_KEYS];

type TrafficLightState = {
  frame: FrameKey;
  duration: number;
};

export class TrafficLight
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  #sequence: TrafficLightState[];
  #currentIndex = 0;
  #timer?: Phaser.Time.TimerEvent;
  #startOffsetMs: number;
  #usePoleVariant: boolean;

  constructor(scene: Phaser.Scene, config: TrafficLightConfig) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.TRAFFIC_LIGHTS,
      TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_OFF,
    );

    this.#startOffsetMs = Math.max(0, config.startOffsetMs ?? 0);
    this.#usePoleVariant = !!config.usePoleVariant;
    this.#sequence = this.#buildSequence(config.ternaryLetters);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true).setDepth(2);

    this.disableObject();
  }

  enableObject(): void {
    this.active = true;
    this.visible = true;
    this.#currentIndex = 0;
    this.#clearTimer();

    if (this.#startOffsetMs > 0) {
      this.setFrame(TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_OFF);
      this.#timer = this.scene.time.delayedCall(this.#startOffsetMs, () => {
        this.#playCurrentState();
      });
    } else {
      this.#playCurrentState();
    }
  }

  disableObject(): void {
    this.active = false;
    this.visible = false;
    this.#clearTimer();
    this.setFrame(TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_OFF);
  }

  destroy(): void {
    this.#clearTimer();
    super.destroy();
  }

  #playCurrentState(): void {
    if (!this.active) {
      return;
    }

    const state = this.#sequence[this.#currentIndex];
    this.setFrame(state.frame);

    this.#timer = this.scene.time.delayedCall(state.duration, () => {
      if (!this.active) {
        return;
      }

      this.#currentIndex = (this.#currentIndex + 1) % this.#sequence.length;
      this.#playCurrentState();
    });
  }

  #clearTimer(): void {
    if (this.#timer) {
      this.#timer.destroy();
      this.#timer = undefined;
    }
  }

  #buildSequence(ternaryLetters: string[]): TrafficLightState[] {
    const sequence: TrafficLightState[] = [];

    const offFrame = this.#usePoleVariant
      ? TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_POLE_OFF
      : TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_OFF;

    ternaryLetters.forEach((ternary) => {
      ternary.split("").forEach((digit, idx, arr) => {
        const frame = this.#digitToFrame(digit);
        const isLastDigit = idx === arr.length - 1;

        sequence.push({
          frame,
          duration: COLOR_DURATION_MS,
        });

        sequence.push({
          frame: offFrame,
          duration: isLastDigit ? LETTER_GAP_MS : DIGIT_GAP_MS,
        });
      });
    });

    return sequence.length > 0
      ? sequence
      : [
          {
            frame: offFrame,
            duration: LETTER_GAP_MS,
          },
        ];
  }

  #digitToFrame(digit: string): FrameKey {
    const frames = this.#usePoleVariant
      ? {
          red: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_POLE_RED,
          yellow: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_POLE_YELLOW,
          green: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_POLE_GREEN,
          off: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_POLE_OFF,
        }
      : {
          red: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_RED,
          yellow: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_YELLOW,
          green: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_GREEN,
          off: TRAFFIC_LIGHTS_FRAME_KEYS.TRAFFIC_OVERHEAD_OFF,
        };

    switch (digit) {
      case "0":
        return frames.red;
      case "1":
        return frames.yellow;
      case "2":
        return frames.green;
      default:
        return frames.off;
    }
  }
}
