import type Phaser from "phaser";
import {
  DEFAULT_UI_TEXT_STYLE,
  DEATH_REASON,
  DIRECTION,
  STORY_FLAG,
} from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { logger } from "../common/logger";
import {
  DYNAMIC_INJECTION_TYPE,
  TILED_LAYER_NAMES,
  VEHICLE_TEXTURE,
} from "../common/tiled/constants";
import {
  getAllLayerNamesWithPrefix,
  getTiledDynamicInjectionObjectsFromMap,
  getTiledPushableObjectsFromMap,
  getTiledPushGoalObjectsFromMap,
  getTiledVehicleObjectsFromMap,
} from "../common/tiled/utils";
import { type GameObject } from "../common/types";
import { PushableComponent } from "../components/pushable-component";
import { Car } from "../entities/objects/car";
import { PushGoal } from "../entities/objects/push-goal";
import { Pushable } from "../entities/objects/pushable";
import { TrafficLight } from "../entities/objects/traffic-light";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

const TRAFFIC_LIGHT_TERNARY_BY_ID: Record<number, string[]> = {
  1: ["001", "200", "010", "022", "100", "111", "012", "011", "012", "201"],
  2: ["110", "100", "021", "022", "202", "002", "210", "110", "002"],
  3: ["111", "120", "111", "012", "112", "202"],
  4: ["201", "100", "220"],
};

const PACKAGE_DELIVERY_FLAG_KEYS = [
  "package_delivery_1",
  "package_delivery_2",
  "package_delivery_3",
] as const;
const PACKAGE_DELIVERY_DIALOG_MESSAGE = "Thanks for the package!";

type PackageDeliveryFlagKey = (typeof PACKAGE_DELIVERY_FLAG_KEYS)[number];

const PACKAGE_DELIVERY_GOAL_IDS = new Set<PackageDeliveryFlagKey>(
  PACKAGE_DELIVERY_FLAG_KEYS,
);

// Mapping from story flag to puzzle info (slug and title) for The Brights
// Trace: story_flag -> interaction_id (FLAG_TO_INTERACTION_MAP) -> puzzle slot (r6pdXX -> r6pXX) -> puzzle slug (ID_TO_PUZZLE_AND_PUZZMON_SLUGS_RAW)
const THE_BRIGHTS_STORY_FLAG_TO_PUZZLE: Record<
  string,
  { slug: string; title: string }
> = {
  city11: { slug: "computation", title: "Computation" }, // r6pd01 -> r6p01
  city12: { slug: "rearranged", title: "Rearranged" }, // r6pd02 -> r6p02
  city13: { slug: "pursuit_of_liberty", title: "Pursuit of Liberty" }, // r6pd03 -> r6p03
  city14: { slug: "musical_numbers", title: "Musical Numbers" }, // r6pd04 -> r6p04
  city15: { slug: "haunted_mansion", title: "Haunted Mansion" }, // r6pd05 -> r6p05
  city16: { slug: "clue_arbiter", title: "Clue Arbiter" }, // r6pd06 -> r6p06
  city17: { slug: "sound_translation", title: "Sound Translation" }, // r6pd07 -> r6p07
  city18: { slug: "permutations", title: "Permutations" }, // r6pd08 -> r6p08
  city19: { slug: "starry_night", title: "Starry Night" }, // r6pd09 -> r6p09
  city20: { slug: "electrical_circuit", title: "Electrical Circuit" }, // r6pd10 -> r6p10
};

export class TheBrightsGameScene extends BaseGameScene {
  private pushGoalsByRoom = new Map<number, PushGoal[]>();
  private pushablesByRoom = new Map<number, Pushable[]>();
  private carsByRoom = new Map<number, Car[]>();
  #trafficLightsByRoom = new Map<number, TrafficLight[]>();
  private static readonly SLOW_ROOMS_START = 11;
  private static readonly SLOW_ROOMS_END = 20;
  private static readonly SLOW_SPEED_MODIFIER = 0.75; // 75% of normal speed
  #solvedText?: Phaser.GameObjects.Text;
  #solvedRoomsThisSession = new Set<number>(); // Track which rooms have shown solved message this session

  constructor() {
    super(SCENE_KEYS.THE_BRIGHTS_GAME_SCENE);
  }

  public create(): void {
    super.create();

    // Create solved message text (initially hidden)
    // Use camera dimensions to ensure correct positioning
    const camera = this.cameras.main;
    this.#solvedText = this.add
      .text(camera.width / 2, camera.height / 2, "SOLVED", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "48px",
        fontFamily: "monospace",
        color: "#00FF00",
        stroke: "#000000",
        strokeThickness: 6,
      })
      .setOrigin(0.5, 0.5)
      .setDepth(2000)
      .setScrollFactor(0, 0)
      .setVisible(false)
      .setAlpha(0);
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      return undefined;
    }

    this.pushGoalsByRoom.clear();
    this.pushablesByRoom.clear();
    this.carsByRoom.clear();
    this.#trafficLightsByRoom.clear();

    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => ({
        name: layerName,
        roomId: parseInt(layerName.split("/")[1], 10),
      }),
    );

    // Process pushables
    const pushableLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.PUSHABLES}`),
    );
    pushableLayers.forEach((layer) => {
      const roomId = parseInt(layer.name.split("/")[1], 10);
      const objects = getTiledPushableObjectsFromMap(map, layer.name);
      const pushables: Pushable[] = [];
      objects.forEach((object) => {
        const pushable = new Pushable(this, object);
        this.pushableGroup.add(pushable);
        pushables.push(pushable);
      });
      if (pushables.length > 0) {
        this.pushablesByRoom.set(roomId, pushables);
      }
    });

    // Process push goals
    const pushGoalLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.PUSH_GOALS}`),
    );
    pushGoalLayers.forEach((layer) => {
      const objects = getTiledPushGoalObjectsFromMap(map, layer.name);
      const pushGoals: PushGoal[] = [];
      objects.forEach((object) => {
        const pushGoal = new PushGoal(this, object);
        // Room 1 goals should not show the green overlay tint
        pushGoal.setIndicatorVisible(layer.roomId !== 1);
        pushGoals.push(pushGoal);
      });
      if (pushGoals.length > 0) {
        this.pushGoalsByRoom.set(layer.roomId, pushGoals);
      }
    });

    // Process vehicles (cars)
    const vehicleLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.VEHICLES}`),
    );
    vehicleLayers.forEach((layer) => {
      const objects = getTiledVehicleObjectsFromMap(map, layer.name);
      logger.info(
        `Loaded ${objects.length} vehicles for room ${layer.roomId} from ${layer.name}`,
      );
      objects.forEach((object) => {
        if (object.texture !== VEHICLE_TEXTURE.CAR) {
          logger.warn(`Unsupported vehicle texture: ${object.texture}`);
          return;
        }
        const car = new Car(this, object);
        this.getCarsForRoom(layer.roomId).push(car);
      });
    });

    this.#createTrafficLights(map, rooms);

    return map;
  }

  getPushGoalsForRoom(roomId: number): PushGoal[] {
    return this.pushGoalsByRoom.get(roomId) ?? [];
  }

  getPushablesForRoom(roomId: number): Pushable[] {
    return this.pushablesByRoom.get(roomId) ?? [];
  }

  getCarsForRoom(roomId: number): Car[] {
    let cars = this.carsByRoom.get(roomId);
    if (!cars) {
      cars = [];
      this.carsByRoom.set(roomId, cars);
    }
    return cars;
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);

    // Enable push goals for this room
    const pushGoals = this.getPushGoalsForRoom(roomId);
    pushGoals.forEach((goal) => {
      goal.enableObject();
    });

    // Enable pushables for this room (they will reset to original position if configured)
    const pushables = this.getPushablesForRoom(roomId);
    pushables.forEach((pushable) => {
      pushable.enableObject();
    });

    // Enable cars for this room
    this.getCarsForRoom(roomId).forEach((car) => {
      car.enableObject();
    });
    logger.info(
      `Enabled ${this.getCarsForRoom(roomId).length} cars in room ${roomId}`,
    );

    // Apply slow speed modifier for rooms 11-20
    if (
      roomId >= TheBrightsGameScene.SLOW_ROOMS_START &&
      roomId <= TheBrightsGameScene.SLOW_ROOMS_END
    ) {
      this.playerObject.setSpeedModifier(
        TheBrightsGameScene.SLOW_SPEED_MODIFIER,
      );
    }

    this.#trafficLightsByRoom.get(roomId)?.forEach((trafficLight) => {
      trafficLight.enableObject();
    });
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();
    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
  }

  private onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix: Phaser.Display.ColorMatrix =
        camera.postFX.addColorMatrix();
      colorMatrix.saturate(0.35);
      colorMatrix.contrast(0.2);
      colorMatrix.brightness(1.2);

      const matrix = colorMatrix.getData();
      matrix[0] *= 1.0;
      matrix[6] *= 1.05;
      matrix[12] *= 1.15;

      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xccf0ff, 1.2, 0.2, false, 0.05, 8);
    }
  };

  protected override disableRoomObjects(roomId: number): void {
    super.disableRoomObjects(roomId);

    // Disable push goals for this room
    const pushGoals = this.getPushGoalsForRoom(roomId);
    pushGoals.forEach((goal) => {
      goal.disableObject();
    });

    this.getCarsForRoom(roomId).forEach((car) => {
      car.disableObject();
    });
    logger.info(
      `Disabled ${this.getCarsForRoom(roomId).length} cars in room ${roomId}`,
    );

    // Reset speed modifier when leaving slow rooms
    if (
      roomId >= TheBrightsGameScene.SLOW_ROOMS_START &&
      roomId <= TheBrightsGameScene.SLOW_ROOMS_END
    ) {
      this.playerObject.resetSpeedModifier();
    }

    this.#trafficLightsByRoom.get(roomId)?.forEach((trafficLight) => {
      trafficLight.disableObject();
    });
  }

  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Cars: collision kills the player
    const allCars: Car[] = Array.from(this.carsByRoom.values()).flat();
    if (allCars.length > 0) {
      logger.info(`Registering car collider for ${allCars.length} cars total`);
      this.physics.add.overlap(this.playerObject, allCars, (player, car) => {
        const carObj = car as Car;
        if (!carObj.visible) {
          return;
        }
        const killZone = carObj.getKillZone();
        if (this.physics.overlap(this.playerObject, killZone)) {
          this.playerObject.setDeathReason(DEATH_REASON.CAR_RUN_OVER);
          this.playerObject.hit(DIRECTION.DOWN, 1);
        }
      });
    }

    // Register overlap between pushables and push goals
    // Create a group of all push goals for overlap detection
    const allPushGoals: PushGoal[] = Array.from(
      this.pushGoalsByRoom.values(),
    ).flat();
    if (allPushGoals.length > 0) {
      const pushGoalGroup = this.add.group(allPushGoals);

      this.physics.add.overlap(
        this.pushableGroup,
        pushGoalGroup,
        (_pushable, _pushGoal) => {
          // When a pushable overlaps with a push goal, check completion
          this.#checkPushGoalsCompletion();
        },
      );
    }
  }

  /**
   * Checks if all push goals in the current room have a pushable on them
   * and all pushables in the room are on a push goal
   */
  #checkPushGoalsCompletion(): void {
    const roomId = this.currentRoomId;
    const pushGoals = this.getPushGoalsForRoom(roomId);
    // Pushables are only considered after they are done sliding.
    const pushables = this.#getActivePushablesForRoom(roomId).filter(
      (pushableObject) => {
        const pushableComponent =
          PushableComponent.getComponent<PushableComponent>(
            pushableObject as GameObject,
          );
        return !pushableComponent.isBeingPushed;
      },
    );

    if (pushGoals.length === 0) {
      return; // No push goals in this room
    }

    this.#handlePackageDeliveryGoals(pushGoals, pushables);

    if (pushables.length === 0) {
      return; // No pushables in this room
    }

    // Check if all goals have a pushable on them
    const allGoalsSatisfied = pushGoals.every((goal) => {
      return pushables.some((pushable) => goal.isPushableOnGoal(pushable));
    });

    // Check if all pushables are on a push goal
    const allPushablesOnGoals = pushables.every((pushable) => {
      return pushGoals.some((goal) => goal.isPushableOnGoal(pushable));
    });

    // Both conditions must be true: all goals have pushables AND all pushables are on goals
    if (allGoalsSatisfied && allPushablesOnGoals) {
      // Only show message if we haven't shown it for this room in this session
      // This prevents spam while still showing it each time you solve it (even after refresh)
      if (!this.#solvedRoomsThisSession.has(roomId)) {
        logger.info(
          `Puzzle solved! All push goals in room ${roomId} have pushables on them, and all pushables are on push goals.`,
        );

        const flagKey = `city${roomId}` as keyof typeof STORY_FLAG;
        const flag = STORY_FLAG[flagKey];
        // Check if the story flag/interaction was already completed before we set it
        const wasAlreadyCompleted =
          flag && this.dataManager.getFlagValue(flag) === "completed";
        if (flag && !wasAlreadyCompleted) {
          this.dataManager.setFlagToCompleted(flag);
          this.dataManager.completeInteraction(flag);
        }

        // Mark this room as solved for this session (prevents spam)
        this.#solvedRoomsThisSession.add(roomId);

        // Show puzzle announcement instead of "SOLVED" message
        const puzzleInfo = THE_BRIGHTS_STORY_FLAG_TO_PUZZLE[flagKey];
        if (puzzleInfo) {
          // Format puzzle name as clickable BBCode link (same format as NPC text)
          const puzzleLink = `[url=/puzzles/${puzzleInfo.slug}][b][color=#801a79]${puzzleInfo.title}[/color][/b][/url]`;

          const message = wasAlreadyCompleted
            ? `Congratulations! You earned ${puzzleLink}! ...or you would have but someone earned it already!`
            : `Congratulations! You earned ${puzzleLink}!`;

          EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
            messages: [message],
            choices: [],
          });
        } else {
          // Fallback to old "SOLVED" message if no puzzle mapping found
          this.#showSolvedMessage();
        }
      }
    } else {
      // If puzzle is no longer solved, remove from solved set so it can show again
      this.#solvedRoomsThisSession.delete(roomId);
    }
  }

  #getActivePushablesForRoom(roomId: number): Phaser.GameObjects.GameObject[] {
    const pushables = this.getPushablesForRoom(roomId);
    if (pushables.length > 0) {
      return pushables;
    }

    return this.pushableGroup
      .getChildren()
      .filter((object) => object.active) as Phaser.GameObjects.GameObject[];
  }

  #handlePackageDeliveryGoals(
    pushGoals: PushGoal[],
    pushables: Phaser.GameObjects.GameObject[],
  ): void {
    let completedAny = false;

    pushGoals.forEach((goal) => {
      const goalIdentifier = goal.identifier as
        | PackageDeliveryFlagKey
        | undefined;

      if (!goalIdentifier || !PACKAGE_DELIVERY_GOAL_IDS.has(goalIdentifier)) {
        return;
      }

      const flag = STORY_FLAG[goalIdentifier];
      if (this.dataManager.getFlagValue(flag) === "completed") {
        return;
      }

      const isDelivered = pushables.some((pushable) =>
        goal.isPushableOnGoal(pushable),
      );
      if (!isDelivered) {
        return;
      }

      this.dataManager.setFlagToCompleted(flag);
      this.dataManager.completeInteraction(flag);
      const deliveredCount = this.#getPackageDeliveryCompletedCount();
      this.#showPackageDeliveryDialog(deliveredCount);
      completedAny = true;
    });

    if (!completedAny) {
      return;
    }

    const allDelivered = PACKAGE_DELIVERY_FLAG_KEYS.every((flagKey) => {
      const flag = STORY_FLAG[flagKey];
      return this.dataManager.getFlagValue(flag) === "completed";
    });

    if (allDelivered) {
      this.#showSolvedMessage();
    }
  }

  #getPackageDeliveryCompletedCount(): number {
    return PACKAGE_DELIVERY_FLAG_KEYS.filter((flagKey) => {
      const flag = STORY_FLAG[flagKey];
      return this.dataManager.getFlagValue(flag) === "completed";
    }).length;
  }

  #showPackageDeliveryDialog(deliveredCount: number): void {
    const total = PACKAGE_DELIVERY_FLAG_KEYS.length;
    const message =
      deliveredCount >= total
        ? "All packages delivered! Thanks!"
        : `${PACKAGE_DELIVERY_DIALOG_MESSAGE} (${deliveredCount}/${total})`;

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [message],
      choices: [],
    });
  }

  /**
   * Shows a flashing "SOLVED" message on the player's screen
   */
  #showSolvedMessage(): void {
    if (!this.#solvedText) {
      return;
    }

    // Reset any existing tweens
    this.tweens.killTweensOf(this.#solvedText);

    // Show and fade in
    this.#solvedText.setVisible(true);
    this.tweens.add({
      targets: this.#solvedText,
      alpha: 1,
      duration: 300,
      ease: "Power2",
      onComplete: () => {
        // Hold for a moment, then fade out
        this.time.delayedCall(1500, () => {
          if (this.#solvedText) {
            this.tweens.add({
              targets: this.#solvedText,
              alpha: 0,
              duration: 500,
              ease: "Power2",
              onComplete: () => {
                if (this.#solvedText) {
                  this.#solvedText.setVisible(false);
                }
              },
            });
          }
        });
      },
    });
  }

  #createTrafficLights(
    map: Phaser.Tilemaps.Tilemap,
    rooms: { name: string; roomId: number }[],
  ): void {
    const dynamicLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.DYNAMIC_INJECTIONS}`),
    );

    dynamicLayers.forEach((layer) => {
      const objects = getTiledDynamicInjectionObjectsFromMap(map, layer.name);
      const trafficLights: TrafficLight[] = [];

      objects.forEach((object) => {
        const isTrafficLightOverhead =
          object.injectionType ===
            DYNAMIC_INJECTION_TYPE.TRAFFIC_LIGHT_OVERHEAD ||
          object.injectionType === DYNAMIC_INJECTION_TYPE.TRAFFIC_LIGHT;
        const isTrafficLightPole =
          object.injectionType === DYNAMIC_INJECTION_TYPE.TRAFFIC_LIGHT_POLE;

        if (!isTrafficLightOverhead && !isTrafficLightPole) {
          return;
        }

        const digits = TRAFFIC_LIGHT_TERNARY_BY_ID[object.id];
        if (!digits) {
          logger.warn(
            `Unknown traffic light id ${object.id} in room ${layer.roomId}`,
          );
          return;
        }

        trafficLights.push(
          new TrafficLight(this, {
            x: object.x,
            y: object.y,
            ternaryLetters: digits,
            usePoleVariant: isTrafficLightPole,
            startOffsetMs: object.offset ?? 0,
          }),
        );
      });

      if (trafficLights.length > 0) {
        this.#trafficLightsByRoom.set(layer.roomId, trafficLights);
      }
    });
  }
}
