import CITY_LEVEL from "../assets/data/levels/city/city.json";
import CITY_BACKGROUND from "../assets/data/levels/city/city_background.png";
import CITY_FOREGROUND from "../assets/data/levels/city/city_foreground.png";
import CITY_EVENTS from "../assets/data/levels/city/events.json";
import CITY_NPCS from "../assets/data/levels/city/npcs.json";
import CITY_READABLES from "../assets/data/levels/city/readables.json";
import CITY1_JSON from "../assets/data/spot_the_diff/city1.json";
import CITY1_IMG from "../assets/data/spot_the_diff/city1.png";
import CITY2_JSON from "../assets/data/spot_the_diff/city2.json";
import CITY2_IMG from "../assets/data/spot_the_diff/city2.png";
import CITY3_JSON from "../assets/data/spot_the_diff/city3.json";
import CITY3_IMG from "../assets/data/spot_the_diff/city3.png";
import CITY4_JSON from "../assets/data/spot_the_diff/city4.json";
import CITY4_IMG from "../assets/data/spot_the_diff/city4.png";
import CANDLESTICK_JSON from "../assets/images/npcs/city/candlestick.json";
import CANDLESTICK_IMG from "../assets/images/npcs/city/candlestick.png";
import OUTLET_JSON from "../assets/images/npcs/city/outlet.json";
import OUTLET_IMG from "../assets/images/npcs/city/outlet.png";
import BOX_IMG from "../assets/images/world_objects/box.png";
import CARS_JSON from "../assets/images/world_objects/cars.json";
import CARS_IMG from "../assets/images/world_objects/cars.png";
import TRAFFIC_LIGHTS_JSON from "../assets/images/world_objects/traffic_lights.json";
import TRAFFIC_LIGHTS_IMG from "../assets/images/world_objects/traffic_lights.png";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class TheBrightsPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.THE_BRIGHTS_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadTheBrightsAssets();
  }

  public create(): void {
    super.create();
    this.#createTheBrightsAnimations();
  }

  #loadTheBrightsAssets(): void {
    // Load city level
    this.load.image(ASSET_KEYS.CITY_BACKGROUND, CITY_BACKGROUND);
    this.load.image(ASSET_KEYS.CITY_FOREGROUND, CITY_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.CITY_LEVEL, CITY_LEVEL);

    // Load candlestick NPC
    this.load.aseprite(
      ASSET_KEYS.CANDLESTICK,
      CANDLESTICK_IMG,
      CANDLESTICK_JSON,
    );

    // Load outlet NPC
    this.load.aseprite(ASSET_KEYS.OUTLET, OUTLET_IMG, OUTLET_JSON);

    // Load box (default pushable texture)
    this.load.image(ASSET_KEYS.BOX, BOX_IMG);

    // Load cars
    this.load.atlas(ASSET_KEYS.CARS, CARS_IMG, CARS_JSON);

    // Load traffic lights
    this.load.aseprite(
      ASSET_KEYS.TRAFFIC_LIGHTS,
      TRAFFIC_LIGHTS_IMG,
      TRAFFIC_LIGHTS_JSON,
    );

    // Load city data
    this.load.json(ASSET_KEYS.EVENTS, CITY_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, CITY_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, CITY_READABLES);

    // Load spot the difference assets
    const spotAssets = [
      { key: "city1", img: CITY1_IMG, json: CITY1_JSON },
      { key: "city2", img: CITY2_IMG, json: CITY2_JSON },
      { key: "city3", img: CITY3_IMG, json: CITY3_JSON },
      { key: "city4", img: CITY4_IMG, json: CITY4_JSON },
    ];
    for (const spot of spotAssets) {
      this.load.image(spot.key, spot.img);
      this.load.json(`${spot.key}_data`, spot.json);
    }
  }

  #createTheBrightsAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.CANDLESTICK);
    this.anims.createFromAseprite(ASSET_KEYS.OUTLET);
    this.anims.createFromAseprite(ASSET_KEYS.TRAFFIC_LIGHTS);
  }
}
