import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadTheBrightsScenes } from "../gameworld/scene-loaders/the-brights";
import TheBrightsBody from "./TheBrightsBody";
import { type TheBrightsState } from "./types";

const TheBrightsManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: TheBrightsState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="the_brights"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadTheBrightsScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <TheBrightsBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("the_brights-root");
if (elem) {
  const { initialTheBrightsState: state, initialTeamState } =
    window as unknown as {
      initialTheBrightsState: TheBrightsState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <TheBrightsManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount TheBrightsManager because #the_brights-root was nowhere to be found",
  );
}
