import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import type { TiledPushableObject } from "../../common/tiled/types";
import type { CustomObject, GameObject } from "../../common/types";
import { PushableComponent } from "../../components/pushable-component";

export class Pushable
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #originalPosition: { x: number; y: number };
  #resetOnEnable = true;

  constructor(scene: Phaser.Scene, config: TiledPushableObject) {
    super(scene, config.x, config.y, ASSET_KEYS.BOX);

    // Store original position from config
    this.#originalPosition = { x: config.x, y: config.y };

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).setSize(12, 12).setOffset(2, 2);
    }

    // Make it pushable (always pushable, no restrictions)
    new PushableComponent(this as unknown as GameObject, {
      pushable: true,
    });
  }

  /**
   * Enables resetting to original position when enableObject() is called
   */
  public setResetOnEnable(reset: boolean): void {
    this.#resetOnEnable = reset;
  }

  public disableObject(): void {
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = false;
    }
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = true;
    }
    this.active = true;
    this.visible = true;

    // Reset to original position if configured to do so
    if (this.#resetOnEnable && this.#originalPosition) {
      this.setPosition(this.#originalPosition.x, this.#originalPosition.y);
      if (this.body) {
        (this.body as Phaser.Physics.Arcade.Body).setVelocity(0, 0);
      }
    }
  }
}
