import * as Phaser from "phaser";
import type { TiledPushGoalObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class PushGoal extends Phaser.GameObjects.Zone implements CustomObject {
  #identifier?: string;
  #visualIndicator?: Phaser.GameObjects.Graphics;

  constructor(scene: Phaser.Scene, config: TiledPushGoalObject) {
    super(scene, config.x, config.y, config.width, config.height);

    this.#identifier = config.identifier;
    this.setOrigin(0, 0);
    scene.add.existing(this);
    scene.physics.world.enable(this);
    (this.body as Phaser.Physics.Arcade.Body).setImmovable(true);

    // Create visual indicator (green-tinted rectangle overlay)
    this.#visualIndicator = scene.add.graphics();
    this.#visualIndicator.fillStyle(0x00ff00, 0.4); // Green with 40% opacity
    this.#visualIndicator.fillRect(
      config.x,
      config.y,
      config.width,
      config.height,
    );
    // Set depth high enough to be visible above background but below most game objects
    this.#visualIndicator.setDepth(0);
    this.#visualIndicator.setVisible(true); // Always show the visual indicator

    // Initially disabled (but visual indicator stays visible)
    this.disableObject();
  }

  /**
   * Checks if a pushable object is overlapping this goal zone
   */
  public isPushableOnGoal(pushable: Phaser.GameObjects.GameObject): boolean {
    if (!this.active || !this.body) {
      return false;
    }

    const pushableBody = (pushable as Phaser.Physics.Arcade.Image).body as
      | Phaser.Physics.Arcade.Body
      | undefined;
    if (!pushableBody) {
      return false;
    }

    return this.scene.physics.overlap(
      this.body as Phaser.Physics.Arcade.Body,
      pushableBody,
    );
  }

  get identifier(): string | undefined {
    return this.#identifier;
  }

  public disableObject(): void {
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = false;
    }
    this.active = false;
    this.visible = false;
    // Visual indicator stays visible even when zone is disabled
  }

  public enableObject(): void {
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = true;
    }
    this.active = true;
    this.visible = true; // Zones need visible=true for collision detection
    // Visual indicator stays visible
  }

  public setIndicatorVisible(visible: boolean): void {
    this.#visualIndicator?.setVisible(visible);
  }

  public destroy(): void {
    if (this.#visualIndicator) {
      this.#visualIndicator.destroy();
      this.#visualIndicator = undefined;
    }
    super.destroy();
  }
}
